std::wstring_view getBrandPath(wchar_t (&path)[N])
{
    DWORD n = GetModuleFileNameW(nullptr, path, N);
    if (n == 0 || n >= N) {
        exit(EXIT_FAILURE);
    }
    return { path, tools::filename(path) };
}
